#!/usr/bin/env python3
from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any


TASK_ID = "CSX-027_Q1"
EVENT_ID = "CSX-027"



DEEPENED_TASK_FRAME = {'group': 'ledger_reframed', 'new_title': 'Compound Heat-Water Mechanism Diagnosis', 'task_mode': 'deep_mechanism_diagnosis', 'mechanism_question': 'Reconstruct the disaster mechanism behind Compound Heat-Water by using the numeric calculations as evidence rather than as a stand-alone score table.', 'mechanism_chain': ['identify the physical driver and event window', 'compute the strongest quantitative evidence streams', 'compare the dominant mechanism with at least one tempting simpler explanation', 'state the bounded operational or scientific interpretation'], 'decisive_evidence_prompt': 'Use the largest computed contrasts, persistence measures, source terms, and report anchors as the decisive evidence hierarchy.', 'rejected_prompt': 'Reject a table-only, peak-only, image-only, exposure-only, or single-threshold interpretation when the calculations require a coupled process explanation.', 'bounded_prompt': 'Keep exposure, image, catalog, and threshold values as bounded evidence; do not turn them into exact loss, damage, or full-causality estimates unless the source explicitly supports that.'}


def _deep_rename_key(key):
    replacements = [
        ("score_ledger", "evidence_rows"),
        ("ledger_rows", "evidence_rows"),
        ("ledger", "evidence_synthesis"),
        ("Ledger", "EvidenceSynthesis"),
        ("consistency", "process_alignment"),
        ("Consistency", "ProcessAlignment"),
        ("threshold", "diagnostic_gate"),
        ("Threshold", "DiagnosticGate"),
        ("gate", "diagnostic_test"),
        ("Gate", "DiagnosticTest"),
        ("score_breakdown", "evidence_score_breakdown"),
        ("score", "evidence_score"),
        ("Score", "EvidenceScore"),
    ]
    out = str(key)
    for old, new in replacements:
        out = out.replace(old, new)
    return out


def _deep_rename_obj(value):
    if isinstance(value, dict):
        return {_deep_rename_key(k): _deep_rename_obj(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_deep_rename_obj(v) for v in value]
    if isinstance(value, str):
        out = value
        replacements = [
            ("ledger", "evidence synthesis"),
            ("Ledger", "Evidence synthesis"),
            ("consistency", "process alignment"),
            ("Consistency", "Process alignment"),
            ("threshold", "diagnostic gate"),
            ("Threshold", "Diagnostic gate"),
        ]
        for old, new in replacements:
            out = out.replace(old, new)
        return out
    return value


def _deep_extract_answer(value):
    if isinstance(value, dict):
        for key in ("final_label", "answer", "classification", "label", "final_interpretation", "diagnosis"):
            if key in value and isinstance(value[key], (str, int, float, bool)):
                return str(value[key])
        for key in ("classification", "threshold_result", "result"):
            if key in value and isinstance(value[key], dict):
                nested = _deep_extract_answer(value[key])
                if nested:
                    return nested
    return "deep_mechanism_diagnosis"


def apply_deepened_task_frame(result):
    frame = dict(DEEPENED_TASK_FRAME)
    old_primary = result.get("primary_gt")
    if not isinstance(old_primary, dict):
        old_primary = {"value": old_primary}
    transformed = {
        "answer": _deep_rename_obj(_deep_extract_answer(old_primary)),
        "task_mode": frame["task_mode"],
        "mechanism_question": frame["mechanism_question"],
        "computed_evidence": _deep_rename_obj(old_primary),
        "mechanism_chain": list(frame["mechanism_chain"]),
        "decisive_evidence": frame["decisive_evidence_prompt"],
        "rejected_simplifications": frame["rejected_prompt"],
        "bounded_interpretation": frame["bounded_prompt"],
    }
    result["primary_gt"] = transformed
    result["task_type"] = "structured_reasoning"
    result["evaluation_mode"] = "hybrid"
    result["subtype"] = frame["task_mode"]
    result["deepened_reframe"] = {
        "group": frame["group"],
        "replaces_table_only_task": True,
        "new_title": frame["new_title"],
    }
    guidance = result.get("answer_guidance")
    if isinstance(guidance, dict):
        guidance["structured_answer"] = transformed
        guidance["answer"] = transformed["answer"]
    else:
        result["answer_guidance"] = {"structured_answer": transformed, "answer": transformed["answer"]}
    result["rubric"] = {
        "total_points": 20,
        "criteria": [
            {"name": "mechanism_diagnosis", "points": 4, "description": "Identifies the dominant physical process and gives the correct compact answer label or an equivalent diagnosis."},
            {"name": "computed_evidence", "points": 5, "description": "Recomputes the quantitative evidence inherited from the original task and preserves units, signs, ratios, and key values."},
            {"name": "evidence_weighting", "points": 4, "description": "Explains which evidence streams are decisive and which are contextual or weaker proxies."},
            {"name": "counterfactual_rejection", "points": 3, "description": "Rejects at least one tempting simplified explanation using the computed values rather than assertion."},
            {"name": "bounded_interpretation", "points": 2, "description": "States scale, timing, proxy, or uncertainty limits without adding unsupported losses or impacts."},
            {"name": "json_contract", "points": 2, "description": "Returns the requested structured mechanism-diagnosis JSON without reverting to a row-only ledger or same-scale consistency table."},
        ],
    }
    return result

def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


ROOT = repo_root()
PKG = ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def load_json(rel_path: str) -> Any:
    with (PKG / rel_path).open("r", encoding="utf-8-sig") as f:
        return json.load(f)


def read_text(rel_path: str) -> str:
    return (PKG / rel_path).read_text(encoding="utf-8", errors="ignore")


def longest_run(values: list[float], labels: list[str], threshold: float) -> dict[str, Any]:
    best_len = 0
    best_start = None
    best_end = None
    cur_len = 0
    cur_start = None
    for idx, value in enumerate(values):
        if value >= threshold:
            if cur_len == 0:
                cur_start = idx
            cur_len += 1
            if cur_len > best_len:
                best_len = cur_len
                best_start = cur_start
                best_end = idx
        else:
            cur_len = 0
            cur_start = None
    return {
        "days": best_len,
        "start": labels[best_start] if best_start is not None else None,
        "end": labels[best_end] if best_end is not None else None,
    }


def exceedance_load(values: list[float], threshold: float) -> float:
    return round(sum(max(value - threshold, 0.0) for value in values), 1)


def extract_number(pattern: str, text: str, label: str) -> float:
    match = re.search(pattern, text, flags=re.IGNORECASE | re.DOTALL)
    if not match:
        raise ValueError(f"Could not extract {label}")
    return float(match.group(1))


def main() -> None:
    event_meta = load_json("metadata/event.json")
    open_meteo = load_json("data/physical_hazard/physical_hazard_001_Open-Meteo_historical_archive.json")
    dnbr = load_json("data/physical_hazard/physical_hazard_008_Sentinel-2_SR_Harmonized_dNBR.json")
    embedding = load_json(
        "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json"
    )
    nasa_html = read_text("data/other/other_003_01_NASA_Earth_Observatory_-_Parched_Poyang_Lake.html.html")

    daily = open_meteo["daily"]
    dates = daily["time"]
    tmax = daily["temperature_2m_max"]
    tmin = daily["temperature_2m_min"]
    apparent = daily["apparent_temperature_max"]

    tmax35_run = longest_run(tmax, dates, 35.0)
    apparent40_run = longest_run(apparent, dates, 40.0)
    tmin25_run = longest_run(tmin, dates, 25.0)
    tmin28_run = longest_run(tmin, dates, 28.0)

    aug06_level_m = extract_number(
        r"By August 6,\s*water levels had declined to\s*([0-9.]+)\s*meters",
        nasa_html,
        "Poyang Lake August 6 level",
    )
    aug30_level_m = extract_number(
        r"registering\s*([0-9.]+)\s*meters\s*\([^)]*\)\s*on August 30",
        nasa_html,
        "Poyang Lake August 30 level",
    )
    early_days = int(
        extract_number(
            r"roughly\s*([0-9]+)\s*days earlier than usual",
            nasa_html,
            "early dry-season timing",
        )
    )

    drop_m = round(aug06_level_m - aug30_level_m, 2)
    drop_rate = round(drop_m / 24, 3)
    dnbr_mean = round(dnbr["stats"]["sentinel2_dnbr_mean"], 3)
    embedding_mean = round(embedding["stats"]["alphaearth_1_minus_cosine_mean"], 3)

    heat_pass = tmax35_run["days"] >= 14 and apparent40_run["days"] >= 14
    recovery_failed = tmin25_run["days"] >= 21 or tmin28_run["days"] >= 7
    water_pass = drop_m >= 3.0 and early_days >= 90
    image_rejected = abs(dnbr_mean) < 0.05 and embedding_mean < 0.05

    computed_evidence = {
        "daytime_heat_load": {
            "tmax35_run_days": tmax35_run["days"],
            "tmax35_run_window": {"start": tmax35_run["start"], "end": tmax35_run["end"]},
            "tmax35_excess_c_days": exceedance_load(tmax, 35.0),
            "apparent40_run_days": apparent40_run["days"],
